// 目录分页：详情页即目录页，200 集/页；total 由详情 keep 带入
fn ytPages(bu, total) {
  let id = str(match(str(bu), 'detail/([a-f0-9-]+)', 1))
  let n = int(default(str(total), '0'), 0)
  if (len(id) == 0 || n <= 200) {
    return ''
  }
  let out = []
  let skip = 200
  while (skip < n) {
    push(out, 'http://www.yuetingba.cn/book/detail/' + id + '/' + str(skip))
    skip = skip + 200
  }
  return out
}
// 详情页的 分类 · 状态
fn ytKind(h) {
  let c = str(match(str(h), '分[ ]*类：</span><span[^>]*>([^<]{1,20})', 1))
  let s = str(match(str(h), '状[ ]*态：</span><span[^>]*>([^<]{1,20})', 1))
  if (len(s) == 0) {
    return c
  }
  if (len(c) == 0) {
    return s
  }
  return c + ' · ' + s
}
